// Precedence, most specific first: screen area > EXTRA > base dictionary.
// English is the last resort for any language, so a missing hi/te key degrades
// to readable English rather than to a raw key name on screen.
const DICT = {
  en: { ...S.en, ...EXTRA.en, ...areaStrings.en },
  hi: { ...S.hi, ...EXTRA.hi, ...areaStrings.hi },
  te: { ...S.te, ...EXTRA.te, ...areaStrings.te },
};
export const t = (lang, key) => DICT[lang]?.[key] || DICT.en?.[key] || key;

